//! Application command line management
//!
//! One URL at a time. --help and --version is automatically
//! generated by clap

use clap::Parser;

#[derive(Parser, Debug)]
#[command(author, version, about, long_about = None)]
#[command(propagate_version = true)]
pub struct Cli {
    /// url that contains an httpdirectory to display
    pub url: String,
}

impl Cli {
    /// Parsing the Cli and returning the structure filled accordingly
    /// to the command line options
    #[must_use]
    pub fn analyze() -> Self {
        Cli::parse()
    }
}
